["events"] = "UNIT_SPELLCAST_START,UNIT_SPELLCAST_CHANNEL_STOP,UNIT_SPELLCAST_CHANNEL_START,UNIT_SPELLCAST_INTERRUPTED,CURRENT_SPELL_CAST_CHANGED,UNIT_SPELLCAST_SUCCEEDED",
