["nanShield:Value"] = {
["outline"] = "OUTLINE",
["wagoID"] = "6HHBMDHTD",
["parent"] = "玩家盾值条（所有帧高占用）",
["displayText_format_p_time_dynamic_threshold"] = 0,
["customText"] = "",
["shadowYOffset"] = -1,
