["actions"] = {
["start"] = {
["custom"] = "local e = aura_env \n\nif not e.btn then \n    local region = WeakAuras.GetRegion(e.id) \n    \n    -- 将父级框架改为 UIParent 避免安全模板污染\n    e.btn = CreateFrame(\"Button\", e.id..\"Button\", UIParent, \"SecureActionButtonTemplate\") \n    e.btn:RegisterForClicks(\"LeftButtonDown\", \"RightButtonDown\")\n    \n    -- 将 macro 赋值放在初始化内\n    e.btn:SetAttribute(\"type1\", \"macro\")\n    e.btn:SetAttribute(\"macrotext1\", \"/use \" .. e.id)\n    \n    e.btn:SetAttribute(\"type2\", \"macro\")\n    e.btn:SetAttribute(\"macrotext2\", \"/cast 制造魔法黄水晶\")\n    \n    e.btn:SetAllPoints(region) \n    e.btn:SetFrameStrata(\"TOOLTIP\")\n    e.btn:SetFrameLevel(9999)\nend \n\nlocal btn = e.btn \n\nbtn:SetScript(\"OnEnter\", function(self)               \n        GameTooltip:SetOwner(self, \"ANCHOR_RIGHT\") \n        GameTooltip:SetText(\n            \"|cffffffff左键：|r\" .. e.id .. \"\\n\"..\n            \"|cffffffff右键：|r制造法力黄水晶\", \n            0, 1, 0, 1, 1\n        )\n        GameTooltip:Show()\nend)\n\nbtn:SetScript(\"OnLeave\", function(self) \n        GameTooltip:Hide() \nend)\n\nbtn:Show()",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "local e = aura_env \nif  _G[e.id..\"Button\"] then \n    local btn = _G[e.id..\"Button\"] \n    btn:Hide()\nend ",
["do_custom"] = true,
