["核心"] = {
["outline"] = "OUTLINE",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["customText"] = "function ()\n    if WeakAuras.IsOptionsOpen() then\n        return ICON_LIST[8]..\":0|t [\"..GetUnitName(\"player\", true)..\"]\\n\"..ICON_LIST[7]..\":0|t [Bearbear-TwistingNether]\\n\"..ICON_LIST[6]..\":0|t [Fåken-TarrenMill]\\n\"..ICON_LIST[5]..\":0|t [Zathyros-Ragnaros]\\n\"..ICON_LIST[4]..\":0|t [Moonrain-TarrenMill]\\n\"..ICON_LIST[3]..\":0|t [Onaj-Ragnaros]\"\n    end\n    if aura_env.state.icon and aura_env.state.name then\n        return aura_env.state.icon..\" [\"..aura_env.state.name..\"]\"\n    end\nend",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "aura_env.timestamp = -1\naura_env.lastMark = 8\naura_env.curMark = 0\n\naura_env.clear = function()\n    local used = {}\n    local curMark = 0\n    if GetRaidTargetIndex(\"player\") then\n        curMark = GetRaidTargetIndex(\"player\") \n    end\n    for unit in WA_IterateGroupMembers() do\n        if GetRaidTargetIndex(unit) then\n            used[GetRaidTargetIndex(unit)] = true\n        end\n    end\n    for i = 1,8 do\n        if not used[i] then\n            SetRaidTarget(\"player\",i)\n            aura_env.lastMark = i\n        end\n    end\n    SetRaidTarget(\"player\",curMark)\n    aura_env.timestamp = GetTime()\n    aura_env.curMark = curMark\nend\n\naura_env.mark = function(allstates,markID,GUID,name)\n    if  (not GetRaidTargetIndex(\"mouseover\")) and UnitGUID(\"mouseover\") == GUID then\n        for i = 1,8 do\n            if allstates[i] and allstates[i].show and allstates[i].GUID == GUID then return end\n        end\n        allstates[markID] = {\n            show = true,\n            changed = true,\n            name = name,\n            GUID = GUID,\n            icon = ICON_LIST[markID]..\":0|t\"\n        }\n        SetRaidTargetIcon(\"mouseover\",markID)\n    end\nend",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["names"] = {
},
["events"] = "CLEU:UNIT_DIED CRAM_CLEAR CRAM_MARK",
["custom"] = "function(allstates,event,...)\n    if (not UnitIsGroupAssistant(\"player\")) and (not UnitIsGroupLeader(\"player\")) then return end\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\"  then\n        if select(11,...)  and select(11,...) > 0 then\n            local markID = select(2,math.frexp(select(11,...)))\n            if allstates[markID] and allstates[markID].show then\n                allstates[markID] = {\n                    show = false,\n                    changed = true,\n                }\n            end\n        end\n    elseif event == \"CRAM_CLEAR\" and ... then\n        for _, state in pairs(allstates) do\n            state.show = false;\n            state.changed = true;\n        end\n        aura_env.clear()\n    elseif event == \"CRAM_MARK\"and ...  then\n        local GUID,name,priorities,limit = ...\n        local count = 0\n        for _,state in pairs(allstates) do\n            if state.show and state.name == name then\n                count = count + 1\n            end\n        end\n        if count >= limit then return end\n        for i = 1,8 do\n            local markID = priorities[i]\n            if not allstates[markID] then\n                aura_env.mark(allstates,markID,GUID,name)\n                break\n            end\n        end\n    end\n    return true\nend",
["subeventPrefix"] = "SPELL",
["check"] = "event",
["spellIds"] = {
},
["subeventSuffix"] = "_CAST_START",
["debuffType"] = "HELPFUL",
},
["untrigger"] = {
},
},
{
["trigger"] = {
["type"] = "custom",
["custom"] = "function()\n    if not aura_env.last or aura_env.last < GetTime() - 0.3 then\n        aura_env.last = GetTime()\n        if GetTime() - aura_env.timestamp < 5 and GetRaidTargetIndex(\"player\") == aura_env.lastMark then\n            SetRaidTarget(\"player\",0)\n            aura_env.timestamp = -1\n        elseif GetRaidTargetIndex(\"player\") == aura_env.curMark then\n            aura_env.timestamp = -1            \n        end\n        return true\n    end\nend",
